#pragma once
#include "pgr1_track.h"
namespace Pgr1Car {
inline bool matches(QString path){return path.endsWith(".nrm",Qt::CaseInsensitive)||path.endsWith(".hrd",Qt::CaseInsensitive)||path.endsWith(".sft",Qt::CaseInsensitive);}
inline bool load(Pgr1Track::Session &s,ReadRequest source,const PatchList &patches,const std::atomic_bool &cancel){
    s.key.clear();s.geometry.clear();s.gpu.clear();s.draws.clear();s.textures.clear();s.images.clear();s.snapshots.clear();s.error.clear();auto fail=[&](QString e){s.error=e;s.draws.clear();return false;};
    if(!matches(source.path))return fail("Open the original PGR1 NRM/HRD/SFT file with its vertex companion.");
    QFileInfo info(source.path);auto find=[&](QString name){for(auto f:info.dir().entryInfoList(QDir::Files))if(f.fileName().compare(name,Qt::CaseInsensitive)==0)return f.absoluteFilePath();return QString();};auto snapshot=[](QString path){QFileInfo f(path);ReadRequest r;r.path=path;r.expectedSize=f.size();r.expectedModified=f.lastModified();return r;};
    s.geometry=Pgr1Data::read(source,patches,cancel,s.error);if(!s.error.isEmpty())return false;s.snapshots.append(source);auto vertexPath=find(info.fileName()+"_v");if(vertexPath.isEmpty())return fail("Missing PGR1 vertex companion: "+info.fileName()+"_v");auto vertexSource=snapshot(vertexPath);auto vertices=Pgr1Data::read(vertexSource,{},cancel,s.error);if(!s.error.isEmpty())return false;s.snapshots.append(vertexSource);
    auto texturePath=find(info.fileName()+"_res");if(texturePath.isEmpty())texturePath=find(info.completeBaseName()+"_default."+info.suffix()+"_res");QByteArray pixels;if(!texturePath.isEmpty()){auto textureSource=snapshot(texturePath);pixels=Pgr1Data::read(textureSource,{},cancel,s.error);if(!s.error.isEmpty())return false;s.snapshots.append(textureSource);}s.gpu=vertices+pixels;
    auto &b=s.geometry;auto fits=[&](qint64 p,qint64 n){return NativeResources::range(p,n,b.size());};auto u=[&](qint64 p){return qFromLittleEndian<quint32>(b.constData()+p);};auto h=[&](qint64 p){return qFromLittleEndian<quint16>(b.constData()+p);};auto f=[&](qint64 p){float v;auto bits=u(p);std::memcpy(&v,&bits,4);return v;};
    if(!fits(0,464)||u(0)!=452||(u(456)&2)==0)return fail("Unsupported PGR1 vehicle header/primary LOD.");qint64 table=u(452);if(!fits(table,4))return fail("Invalid PGR1 vehicle texture directory.");auto count=u(table);if(count>10000||!fits(table+4,qint64(count)*44))return fail("Invalid PGR1 vehicle texture records.");int numberPlate=-1;
    for(quint32 i=0;i<count;++i){qint64 at=table+4+i*44;auto name=b.mid(at,32);int end=name.indexOf('\0');if(end<0)return fail("Unterminated PGR1 vehicle texture name.");Pgr1Track::Texture t;t.name=QString::fromLatin1(name.left(end));t.width=h(at+32);t.height=h(at+34);int format=h(at+36),extra=h(at+38);t.code=format;if(t.name=="NumPlate")numberPlate=i;if(!imageValidSize(t.width,t.height))return fail("Invalid PGR1 vehicle texture size.");qint64 offset=u(at+40);if(!pixels.isEmpty()&&((format==6&&extra==0)||(format==10&&extra==8))){t.size=qint64((t.width+3)/4)*((t.height+3)/4)*(format==6?8:16);if(!NativeResources::range(offset,t.size,pixels.size()))return fail("PGR1 vehicle texture exceeds its companion.");}t.offset=vertices.size()+offset;s.textures.append(t);if(!t.size){QImage placeholder(2,2,QImage::Format_RGBA8888);placeholder.fill(QColor(150,150,150));s.images[i]=placeholder;}}
    Pgr1Track::Texture glass;glass.name="Glass approximation";glass.width=glass.height=2;int glassId=s.textures.size();s.textures.append(glass);QImage glassImage(2,2,QImage::Format_RGBA8888);glassImage.fill(QColor(70,85,95,100));s.images[glassId]=glassImage;
    qint64 lod=(u(456)&1)?460:464;if(!fits(lod,28))return fail("Incomplete PGR1 primary LOD.");auto groups=u(lod+8);if(groups<1||groups>10000)return fail("Invalid PGR1 vehicle group count.");qint64 at=lod+28;float wheel[3]={f(92),f(96),f(100)};for(float v:wheel)if(!std::isfinite(v)||std::abs(v)>1e5)return fail("Invalid PGR1 wheel placement.");
    for(quint32 group=0;group<groups;++group){if(cancel.load())return fail("PGR1 vehicle scan canceled.");if(!fits(at,60))return fail("Truncated PGR1 vehicle group.");auto size=u(at);int nv=h(at+36),ni=h(at+38),nm=h(at+40),nameLength=h(at+46);qint64 vbo=u(at+56),indices=at+60,subs=(indices+ni*2+3)&~qint64(3),nameAt=subs+nm*8;if(nv<3||!NativeResources::range(vbo,qint64(nv)*24,vertices.size())||!fits(nameAt,nameLength)||nameAt+nameLength>table)return fail("Invalid PGR1 vehicle group ranges.");auto name=QString::fromLatin1(b.mid(nameAt,nameLength).split('\0').first());QVector3D center(f(at+8),f(at+12),f(at+16));for(int axis=0;axis<3;++axis)if(!std::isfinite(center[axis])||std::abs(center[axis])>1e5)return fail("Invalid PGR1 group position.");if(name.endsWith("FL"))center={-wheel[0],0,wheel[1]};else if(name.endsWith("FR"))center={wheel[0],0,wheel[1]};else if(name.endsWith("BL"))center={-wheel[0],0,wheel[2]};else if(name.endsWith("BR"))center={wheel[0],0,wheel[2]};
        for(int j=0;j<nv;++j)for(int axis=0;axis<3;++axis){float value;auto bits=qFromLittleEndian<quint32>(vertices.constData()+vbo+j*24+axis*4);std::memcpy(&value,&bits,4);if(!std::isfinite(value)||std::abs(value)>1e7)return fail("Invalid PGR1 vehicle vertex.");}for(int j=0;j<ni;++j)if(h(indices+j*2)>=nv)return fail("PGR1 vehicle index exceeds its group.");
        bool alternate=name=="SCR"||name.endsWith("_D"),isGlass=name=="WIN"||name=="WSM"||name=="WS2"||name=="WSD"||name.startsWith("HLG");
        for(int j=0;j<nm;++j){auto p=subs+j*8;int mat=h(p),first=h(p+4),n=h(p+6)+2;if(first+n>ni||mat>=int(count))return fail("Invalid PGR1 vehicle strip/material.");if(isGlass)mat=glassId;else if((name=="NP"||name=="NP2")&&numberPlate>=0)mat=numberPlate;if(!alternate)s.draws.append({at,vbo,indices+first*2,nv,n,24,mat,center});}at=(nameAt+nameLength+3)&~qint64(3);if(!size)break;
    }
    if(s.draws.isEmpty()||!Pgr1Track::unchanged(s))return fail("PGR1 vehicle has no supported groups or its resources changed.");s.key=QString::fromUtf8(QJsonDocument(Pgr1Track::identity(s.snapshots)).toJson(QJsonDocument::Compact));return true;
}
inline QJsonObject scan(ReadRequest source,const PatchList &patches,const std::atomic_bool &cancel){if(!matches(source.path))return {};Pgr1Track::Session s;if(!Pgr1Car::load(s,source,patches,cancel))return {{"notes",QJsonArray{s.error}}};QMap<int,qint64> counts;for(auto d:s.draws)counts[d.material]+=d.count;QJsonArray rows;for(auto it=counts.begin();it!=counts.end();++it)rows.append(QJsonObject{{"name","PGR1 vehicle / "+s.textures[it.key()].name},{"profileId","native-pgr1-car"},{"nativeDecoder",true},{"profileName","PGR1 primary vehicle LOD"},{"objectOffset",QString::number(it.key())},{"pgr1Resources",Pgr1Track::identity(s.snapshots)},{"settings",QJsonObject{{"vertexCount",it.value()*3},{"indexCount",it.value()*3}}},{"basis","Native primary-LOD strips with vertex and texture companions, local/wheel placements and source material IDs. SCR/damaged alternatives excluded; roof/component alternatives and original shaders remain unresolved."}});return {{"candidates",rows},{"notes",QJsonArray{QString("PGR1 vehicle: %1 primary-LOD material groups. Keep the _v and _res/default texture companions beside the original model. Original shaders and component-state assembly remain approximate.").arg(rows.size())}}};}
inline MeshResult decode(ReadRequest source,const PatchList &patches,const QJsonObject &candidate,const std::atomic_bool &cancel,Pgr1Track::Session *cache=nullptr){Pgr1Track::Session local;auto &s=cache?*cache:local;{QMutexLocker lock(&s.mutex);auto key=QString::fromUtf8(QJsonDocument(candidate["pgr1Resources"].toArray()).toJson(QJsonDocument::Compact));if(s.geometry.isEmpty()||s.key!=key){if(!Pgr1Car::load(s,source,patches,cancel)){MeshResult out;out.error=s.error;return out;}}}auto result=Pgr1Track::decode(source,patches,candidate,cancel,&s);if(result.surface){auto &material=result.surface->material;material.sourceBindings["format"]="PGR1 vehicle";material.sourceBindings["lod"]=0;material.sourceBindings["componentStatesResolved"]=false;if(material.name=="Glass approximation"){material.alphaMask=false;material.sourceBindings["unsupportedTexturePlaceholder"]=false;material.sourceBindings["approximateGlass"]=true;}}return result;}
}
